mem = [0, 1]
total_sum = 1

for i in range(2, n + 1):
    sqrt_i = isqrt(i)
    current = total_sum

    for f in range(2, sqrt_i + 1):
        current = add_mod(current, mem[i // f])

    prev_bound = i
    for j in range(1, i // (sqrt_i + 1) + 1):
        next_bound = i // (j + 1)
