from math import sqrt

def read():
    return list(map(int, input().split()))

def mod_sum(x, y):
    return (x + y) % mod

def mod_prod(x, y):
    return (x * y) % mod

n, mod = read()
cache = [0, 1]
cumulative = 1

for step in range(2, n + 1):
    bound = int(sqrt(step)) + 1
    temp = cumulative

    for d in range(2, bound):
        temp = mod_sum(temp, cache[step // d])

    high = step
    for t in range(1, step // bound + 1):
        low = step // (t + 1)
        temp = mod_sum(temp, mod_prod(high - low, cache[t]))
        high = low

    cumulative = mod_sum(cumulative, temp)
    cache.append(temp)

print(cache[-1])

primes = []
for p in range(2, 6000):
    is_prime = True
    for p2 in primes:
        if p2*p2 > p:
            break
        if p % p2==0:
            is_prime = False
            break
    if is_prime:
        primes.append(p)
        
def factor(n):
    d = {}
    for p in primes:
        if p*p > n:
            break
        if n % p==0:
            c = 0
            while n % p==0:
                n = n//p
                c+=1
            d[p] = c
    if n > 1:
        d[n] = 1
