# Use iterative DP with explicit table instead of recursion
def solve_iterative(N, k_target, flag_target):
    # invnum for permutations of length up to N
    max_inv = (N * (N - 1)) // 2

    # dp[length][k_diff][flag] = count
    # We'll use dictionary for sparse storage
    dp = {}

    # Base case: length 1
    for k in range(-max_inv - 1, max_inv + 2):
        for f in [0, 1]:
            if f:
                dp[(1, k, f)] = 0
            else:
                dp[(1, k, f)] = 1 if k < 0 else 0

    # Fill DP table
    for length in range(2, N + 1):
        invnum_INF = (length * (length - 1)) // 2
        for k in range(-invnum_INF - 1, invnum_INF + 1):
            for f in [0, 1]:
                res = 0
                for delta in range(-length + 1, length):
                    if f and delta > 0:
                        continue
                    wt = min(length - delta, delta + length)
                    prev_k = k - delta
                    prev_f = (delta == 0) & f
                    if (length - 1, prev_k, prev_f) in dp:
                        res += dp[(length - 1, prev_k, prev_f)] * wt
                        res %= mod
                dp[(length, k, f)] = res % mod

    return dp.get((N, k_target, flag_target), 0)

