def tf(n, M):
    C = [0] * (n+1)
    C[n] = 1
    for k in reversed(range(n)):
        C[k] = (C[k+1] * (k+1)) % M
        if not C[k]:
            break
    return C

def app(n, M):
    K = [[[1]]]
    for i in range(n-1):
        Ki = K[i]
        ni = len(Ki)
        Ki_ = [[0] * (i+2) for _ in range(ni + i + 1)]
        K.append(Ki_)
        for j, Kij in enumerate(Ki):
            for k, v in enumerate(Kij):
                for h in range(i+1):
                    Ki_[j+h][k] += v
                    Ki_[j+h][k] %= M
                Ki_[j + i + 1][i+1] += v
                Ki_[j + i + 1][i+1] %= M

    # C = comb(n, M)[n]
    C = tf(n, M)
    s = 0
    for i in range(1, n):
        Ki = K[i]
        ni = len(Ki)
        mi = len(Ki[0])
        Si = [[None] * mi for _ in range(ni)]
        for j in range(ni):
            Si[j][mi-1] = Ki[j][mi-1]
            for k in reversed(range(mi-1)):
                Si[j][k] = (Ki[j][k] + Si[j][k+1]) % M
        for j in range(1, ni):
            for k in range(mi):
                Si[j][k] += Si[j-1][k]
                Si[j][k] %= M
        # log("i", i, "Ki", Ki, "Si", Si)

        si = 0
        for j in range(1, ni):
            for k in range(mi-1):
                si += (Ki[j][k] * Si[j-1][k+1]) % M
                si %= M
        # log("  si", si)

        c = C[i+1]
        # log("  n", n, "k", i+1, "c", c)
        si *= c
        si %= M
        s += si
        s %= M

    return s


